/** Drive the actual Add references menu and completed-task picker without changing a live profile. */
async page => {
  const errors = [], assert = (value, message) => { if (!value) throw new Error(message) }
  page.on('pageerror', error => errors.push(error.message))
  await page.route('**/api/visual-curator/resource**', route => route.fulfill({ status: 200, contentType: 'image/svg+xml', body: '<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600"><rect width="800" height="600" fill="#34534a"/></svg>' }))
  await page.setViewportSize({ width: 1360, height: 900 }); await page.emulateMedia({ reducedMotion: 'reduce' }); await page.reload()
  await page.evaluate(() => { window.feedbackFixture.setMode('workbench'); window.feedbackFixture.setScenario('task-reference') })
  const menu = page.getByRole('button', { name: '添加引用', exact: true })
  await menu.click(); await page.getByRole('menuitem', { name: '引用已完成找图任务', exact: true }).click()
  const dialog = page.locator('.vc-task-reference-modal'); await dialog.waitFor()
  const initial = await dialog.boundingBox()
  assert(initial.height >= 800, 'The workspace must retain its height before a task is selected')
  for (const dark of [false, true]) {
    await page.evaluate(value => window.feedbackFixture.theme(value), dark)
    const glass = await dialog.evaluate(node => ({ background: getComputedStyle(node, '::before').backgroundColor, filter: getComputedStyle(node, '::before').backdropFilter }))
    const alpha = Number(glass.background.match(/(?:,|\/)\s*([\d.]+)\s*\)$/)?.[1] ?? 1)
    assert(alpha >= 0.75 && alpha < 0.9 && glass.filter !== 'none', 'The picker needs a readable frosted surface in both themes')
  }
  await dialog.locator('.vc-task-reference-task-list').getByRole('button').filter({ hasText: '已完成的车辆找图' }).click()
  await page.waitForFunction(() => document.querySelectorAll('.vc-task-reference-grid > figure').length === 7)
  const contained = await dialog.locator('.vc-image-preview > img').evaluateAll(nodes => nodes.map(node => { const image = node.getBoundingClientRect(), frame = node.closest('.vc-reference-preview').getBoundingClientRect(); return image.width <= frame.width + 1 && image.height <= frame.height + 1 && image.left >= frame.left - 1 && image.top >= frame.top - 1 && getComputedStyle(node).objectFit === 'contain' }))
  assert(contained.length === 7 && contained.every(Boolean), 'Thumbnails must fit their frames instead of clipping an original-sized image')
  await dialog.getByRole('button', { name: '反例参考', exact: true }).click()
  const selectImage = dialog.locator('.vc-task-reference-grid > figure').nth(1).locator('.vc-image-preview')
  await selectImage.click()
  assert(await dialog.getByRole('checkbox', { name: '任务候选 2', exact: true }).isChecked(), 'Left-clicking the image must select it')
  await selectImage.click({ button: 'right' })
  const lightbox = page.getByRole('dialog', { name: '预览图片', exact: true }); await lightbox.waitFor()
  assert(await dialog.getByRole('checkbox', { name: '任务候选 2', exact: true }).isChecked(), 'Right-clicking must leave selection unchanged')
  await lightbox.getByRole('button', { name: '关闭', exact: true }).click()
  await dialog.locator('.vc-task-reference-footer').getByRole('button', { name: '清空选择', exact: true }).click()
  assert(!await dialog.getByRole('checkbox', { name: '任务候选 2', exact: true }).isChecked(), 'Clear selection must leave the task and images available')
  await dialog.getByRole('checkbox', { name: '任务候选 2', exact: true }).check()
  await dialog.getByRole('button', { name: '全屏查看', exact: true }).click()
  const fullscreen = await dialog.boundingBox()
  assert(fullscreen.x === 0 && fullscreen.y === 0 && fullscreen.width === 1360 && fullscreen.height === 900, 'Maximize must fill the viewport')
  assert(await dialog.getByRole('checkbox', { name: '任务候选 2', exact: true }).isChecked(), 'Maximize must retain selection')
  await dialog.getByRole('button', { name: '还原弹窗', exact: true }).click()
  const restored = await dialog.boundingBox()
  assert(Math.abs(restored.width - initial.width) < 1 && Math.abs(restored.height - initial.height) < 1, 'Restore must return to the previous dialog size')
  const beforeSelectedView = await page.evaluate(() => window.feedbackFixture.state.taskReferenceReads.length)
  await dialog.getByRole('button', { name: /仅看已选/ }).click()
  await page.waitForFunction(() => document.querySelectorAll('.vc-task-reference-grid > figure').length === 1)
  assert(await page.evaluate(() => window.feedbackFixture.state.taskReferenceReads.length) === beforeSelectedView, 'Selected-only view must not refetch the task')
  await dialog.getByRole('button', { name: /仅看已选/ }).click()
  await page.waitForFunction(() => document.querySelectorAll('.vc-task-reference-grid > figure').length === 7)
  const firstReads = await page.evaluate(() => window.feedbackFixture.state.taskReferenceReads.filter(row => row.runId === 'completed-search' && row.resultFilter === 'all'))
  assert(firstReads.length === 2 && firstReads[1].pageToken === '4', 'The bottom sentinel must append each page once without a manual load action')
  assert(await dialog.getByRole('checkbox', { name: '任务候选 2', exact: true }).isChecked(), 'Paging must retain the selected counterexample')
  await page.setViewportSize({ width: 1360, height: 560 })
  const results = dialog.locator('.vc-task-reference-results'), toolbar = dialog.locator('.vc-task-reference-toolbar'), footer = dialog.locator('.vc-task-reference-footer')
  const controls = { top: (await toolbar.boundingBox()).y, bottom: (await footer.boundingBox()).y }
  await results.hover(); await page.mouse.wheel(0, 600)
  await page.waitForFunction(() => document.querySelector('.vc-task-reference-results').scrollTop > 0)
  assert(Math.abs((await toolbar.boundingBox()).y - controls.top) < 1 && Math.abs((await footer.boundingBox()).y - controls.bottom) < 1, 'Image scrolling must keep filters and actions fixed')
  const scroll = await results.evaluate(node => node.scrollTop)
  const taskList = dialog.locator('.vc-task-reference-task-list')
  await taskList.getByRole('button').filter({ hasText: '上一次完成的图片检索' }).click()
  await dialog.getByRole('checkbox', { name: '上次任务候选 3', exact: true }).check()
  await taskList.getByRole('button').filter({ hasText: '已完成的车辆找图' }).click()
  assert(await dialog.getByRole('checkbox', { name: '任务候选 2', exact: true }).isChecked(), 'Switching searches must retain the first selection')
  assert(Math.abs(await results.evaluate(node => node.scrollTop) - scroll) < 1, 'Cached searches must restore their own scroll position')
  assert(await page.evaluate(() => window.feedbackFixture.state.taskReferenceReads.filter(row => row.runId === 'completed-search' && row.resultFilter === 'all').length) === firstReads.length, 'Returning to loaded pages must not repeat their requests')
  const beforeCrossSelected = await page.evaluate(() => window.feedbackFixture.state.taskReferenceReads.length)
  await dialog.getByRole('button', { name: /仅看已选/ }).click()
  assert(await dialog.locator('.vc-task-reference-grid > figure').count() === 2, 'Selected-only must include images from every chosen search')
  assert(await dialog.getByRole('checkbox', { name: '上次任务候选 3', exact: true }).isChecked(), 'The second search selection must remain available in the first search')
  assert(await page.evaluate(() => window.feedbackFixture.state.taskReferenceReads.length) === beforeCrossSelected, 'Cross-task selected view must use retained selection data')
  await dialog.getByRole('button', { name: /仅看已选/ }).click()
  await page.setViewportSize({ width: 1360, height: 900 })
  await dialog.getByRole('button', { name: /不符合风格/, exact: true }).click()
  await page.waitForFunction(() => document.querySelectorAll('.vc-task-reference-grid > figure').length === 3)
  assert(await dialog.getByRole('checkbox', { name: '任务候选 2', exact: true }).isChecked(), 'Filtering must retain selection')
  await page.evaluate(() => { window.feedbackFixture.state.taskReferenceDropOnce = true })
  await footer.getByRole('button', { name: /^添加反例参考/ }).click()
  await dialog.getByRole('alert').filter({ hasText: '暂未确认任务是否已受理' }).waitFor()
  assert(await dialog.getByRole('checkbox', { name: '任务候选 2', exact: true }).isDisabled(), 'An unknown write must freeze its original selection')
  await footer.getByRole('button', { name: /^重试/ }).click()
  await dialog.waitFor({ state: 'hidden' })
  const submissions = await page.evaluate(() => window.feedbackFixture.state.runCommands.filter(([operation]) => operation === 'task-reference-start').map(([, args]) => args))
  assert(submissions.length === 2 && JSON.stringify(submissions[0]) === JSON.stringify(submissions[1]), 'Retry must preserve the exact operation and selection')
  assert(submissions[0].role === 'negative' && JSON.stringify(submissions[0].images) === JSON.stringify([{ runId: 'completed-search', imageVersionId: 'task-reference-1' }, { runId: 'completed-search-previous', imageVersionId: 'previous-task-reference-2' }]), 'Only explicitly chosen counterexamples and their original searches may be added')
  const progress = page.locator('[data-gallery-task]')
  await progress.filter({ hasText: '正在后台引入' }).waitFor()
  assert((await progress.innerText()).includes('0 / 2'), 'An accepted task must show background progress on the collection page')
  await page.evaluate(() => window.feedbackFixture.setTaskReferenceProgress(1))
  await page.waitForFunction(() => document.querySelector('[data-gallery-task]')?.textContent.includes('1 / 2'))
  await page.evaluate(() => window.feedbackFixture.setTaskReferenceProgress(2, 'completed'))
  await progress.filter({ hasText: '引用已完成' }).waitFor()
  assert((await progress.innerText()).includes('2 / 2'), 'A completed background task must retain its final result on the page')
  await page.setViewportSize({ width: 1360, height: 560 })
  await page.evaluate(() => { window.feedbackFixture.state.taskReferenceImageCount = 31; window.feedbackFixture.state.taskReferenceReadFailOnce = true; window.feedbackFixture.state.taskReferenceReads = [] })
  await menu.click(); await page.getByRole('menuitem', { name: '引用已完成找图任务', exact: true }).click()
  await dialog.locator('.vc-task-reference-task-list').getByRole('button').filter({ hasText: '已完成的车辆找图' }).click()
  await dialog.getByRole('alert').filter({ hasText: '暂时无法加载任务图片' }).waitFor()
  const failedReads = await page.evaluate(() => window.feedbackFixture.state.taskReferenceReads.length)
  await page.evaluate(() => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(() => requestAnimationFrame(resolve)))))
  assert(await page.evaluate(() => window.feedbackFixture.state.taskReferenceReads.length) === failedReads, 'A failed page must wait for explicit retry instead of looping at the bottom')
  assert(await dialog.locator('.vc-task-reference-grid > figure').count() === 4, 'A failed next page must retain already loaded candidates')
  await dialog.getByRole('checkbox', { name: '任务候选 2', exact: true }).check()
  await page.evaluate(() => { window.feedbackFixture.state.taskReferenceReadGate = new Promise(resolve => { window.feedbackFixture.state.taskReferenceReleaseRead = resolve }) })
  await dialog.getByRole('alert').getByRole('button', { name: '重试', exact: true }).click()
  await page.waitForFunction(count => window.feedbackFixture.state.taskReferenceReads.length === count + 1, failedReads)
  await page.setViewportSize({ width: 1320, height: 560 })
  await page.evaluate(() => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))))
  assert(await page.evaluate(() => window.feedbackFixture.state.taskReferenceReads.length) === failedReads + 1, 'An in-flight cursor must not be requested again when the viewport changes')
  await dialog.locator('.vc-task-reference-task-list').getByRole('button').filter({ hasText: '上一次完成的图片检索' }).click()
  await dialog.getByRole('checkbox', { name: '上次任务候选 3', exact: true }).check()
  await page.evaluate(() => { window.feedbackFixture.state.taskReferenceReleaseRead(); window.feedbackFixture.state.taskReferenceReadGate = null })
  await page.waitForFunction(() => [...document.querySelectorAll('.vc-task-reference-grid input')].length >= 4)
  assert(await dialog.getByRole('checkbox', { name: '任务候选 2', exact: true }).count() === 0, 'A late response from the previous task must not enter the new task')
  await dialog.locator('.vc-task-reference-task-list').getByRole('button').filter({ hasText: '已完成的车辆找图' }).click()
  assert(await dialog.getByRole('checkbox', { name: '任务候选 2', exact: true }).isChecked(), 'Retry and an aborted page must retain all task selections')
  for (let step = 0; step < 10; step++) {
    const count = await dialog.locator('.vc-task-reference-grid > figure').count()
    if (count === 31) break
    await results.evaluate(node => { node.scrollTop = node.scrollHeight })
    await page.waitForFunction(previous => document.querySelectorAll('.vc-task-reference-grid > figure').length > previous, count)
  }
  assert(await dialog.locator('.vc-task-reference-grid > figure').count() === 31, 'Scrolling to the bottom must load every page, including the final partial page')
  const imageIds = await dialog.getByRole('checkbox').evaluateAll(nodes => nodes.map(node => node.getAttribute('aria-label') || node.closest('label')?.textContent))
  assert(new Set(imageIds).size === 31, 'Merged pages must not duplicate candidate cards')
  await dialog.getByRole('button', { name: /仅看已选/ }).click()
  assert(await dialog.locator('.vc-task-reference-grid > figure').count() === 2, 'Both task selections must survive errors, cancellation and pagination')
  await dialog.locator('.vc-task-reference-footer').getByRole('button', { name: '关闭', exact: true }).click()
  await page.evaluate(() => { window.feedbackFixture.state.taskReferenceImageCount = 40; window.feedbackFixture.state.taskReferenceReads = [] })
  await menu.click(); await page.getByRole('menuitem', { name: '引用已完成找图任务', exact: true }).click()
  await dialog.locator('.vc-task-reference-task-list').getByRole('button').filter({ hasText: '上一次完成的图片检索' }).click()
  await dialog.getByRole('checkbox', { name: '上次任务候选 3', exact: true }).check()
  await dialog.locator('.vc-task-reference-task-list').getByRole('button').filter({ hasText: '已完成的车辆找图' }).click()
  await page.waitForFunction(() => document.querySelector('.vc-task-more')?.disabled === false)
  const beforeAll = await dialog.locator('.vc-task-reference-grid > figure').count()
  assert(beforeAll < 40, 'The select-all case needs unloaded pages')
  await dialog.getByRole('button', { name: '全选', exact: true }).click()
  await dialog.getByText('已达选择上限', { exact: true }).waitFor()
  const loadedAfterAll = await dialog.locator('.vc-task-reference-grid > figure').count()
  assert(loadedAfterAll > beforeAll && loadedAfterAll < 40, 'Select all must enumerate later pages and stop when the global cap is reached')
  assert((await footer.innerText()).includes('已选图片') && (await footer.innerText()).includes('已选任务'), 'The footer must separate the image total and task count')
  await dialog.getByRole('button', { name: /仅看已选/ }).click()
  assert(await dialog.locator('.vc-task-reference-grid > figure').count() === 30, 'The total selection cap applies across searches')
  assert(await dialog.getByRole('checkbox', { name: '上次任务候选 3', exact: true }).isChecked(), 'Select all must keep the other search selection')
  await page.setViewportSize({ width: 390, height: 844 })
  assert(await dialog.evaluate(node => node.getBoundingClientRect().right <= innerWidth && node.getBoundingClientRect().left >= 0), 'Picker must fit the narrow viewport')
  assert(!await dialog.locator('.vc-task-reference-rail').isVisible() && await dialog.locator('.vc-task-reference-mobile-task').isVisible(), 'Narrow layout must replace the rail with a task selector')
  assert(await footer.evaluate(node => node.scrollWidth <= node.clientWidth), 'The selected total and task badge must wrap within the narrow footer')
  await footer.getByRole('button', { name: '清空选择', exact: true }).click()
  assert(await dialog.locator('.vc-task-reference-selected-total strong').innerText() === '0', 'Clear must also cancel any select-all intent')
  await footer.getByRole('button', { name: '关闭', exact: true }).click()
  const result = { reachableFromMenu: true, completedTaskSelection: true, negativeRole: true, rejectedCandidatesVisible: true, pageableBeyondFour: true, selectionRetained: true, unknownWriteKeepsIdentity: true, selectedOnlyImport: true, resultShown: true, persistentWorkspace: true, glassThemes: true, containedThumbnails: true, fullscreenRestores: true, selectedViewNoRefetch: true, fixedControls: true, responsiveTaskNavigation: true, narrowFits: true, autoPaging: true, crossTaskSelection: true, cachedPagesNoRefetch: true, restoredTaskScroll: true, crossTaskImport: true, failedPagingNoLoop: true, lateResponsesIgnored: true, allPagesByScrolling: true, leftClickSelects: true, rightClickPreviews: true, selectAllAcrossPages: true, selectAllKeepsOtherTasks: true, selectAllRespectsLimit: true, backgroundAdmissionCloses: true, pageProgress: true, pageCompletion: true, selectionFooterReadable: true, errors }
  const expected = await page.evaluate(async () => (await fetch('task-reference-ui.expected.json')).json())
  assert(JSON.stringify(result) === JSON.stringify(expected), 'Task reference UI output differs')
  return result
}
